void ScrollBar::mouseWheelMove(const MouseEvent&,const MouseWheelDetails&w){setCurrentRangeStart(start_-std::copysign(step_,w.deltaY));}
Viewport::Viewport(){addAndMakeVisible(horizontal_);addAndMakeVisible(vertical_);horizontal_.addListener(this);vertical_.addListener(this);}
Viewport::~Viewport(){setViewedComponent(nullptr,false);}
void Viewport::setViewedComponent(Component*c,bool own){if(content_==c)return;if(content_)removeChildComponent(content_);owned_.reset();content_=c;if(own)owned_.reset(c);if(c){addAndMakeVisible(*c,0);}updateContent();}
int Viewport::getMaximumVisibleWidth()const{return std::max(0,getWidth()-(showVertical_&&content_&&content_->getHeight()>getHeight()?thickness_:0));}
int Viewport::getMaximumVisibleHeight()const{return std::max(0,getHeight()-(showHorizontal_&&content_&&content_->getWidth()>getWidth()?thickness_:0));}
