void Viewport::updateContent(){if(updating_)return;updating_=true;struct Finish{bool&v;~Finish(){v=false;}}finish{updating_};const int width=content_?content_->getWidth():0,height=content_?content_->getHeight():0;scrollX_=std::clamp(scrollX_,0,std::max(0,width-getMaximumVisibleWidth()));scrollY_=std::clamp(scrollY_,0,std::max(0,height-getMaximumVisibleHeight()));if(content_)content_->setTopLeftPosition(-scrollX_,-scrollY_);vertical_.setVisible(showVertical_&&height>getHeight());horizontal_.setVisible(showHorizontal_&&width>getWidth());vertical_.setBounds(getWidth()-thickness_,0,thickness_,getMaximumVisibleHeight());horizontal_.setBounds(0,getHeight()-thickness_,getMaximumVisibleWidth(),thickness_);vertical_.setRangeLimits(0,std::max(height,getMaximumVisibleHeight()));vertical_.setCurrentRange(scrollY_,getMaximumVisibleHeight(),dontSendNotification);horizontal_.setRangeLimits(0,std::max(width,getMaximumVisibleWidth()));horizontal_.setCurrentRange(scrollX_,getMaximumVisibleWidth(),dontSendNotification);repaint();}
void Viewport::resized(){updateContent();visibleAreaChanged(getViewArea());if(onVisibleAreaChanged)onVisibleAreaChanged(getViewArea());}void Viewport::childBoundsChanged(Component*c){if(c==content_)updateContent();}
void Viewport::scrollBarMoved(ScrollBar*bar,double start){if(!updating_)setViewPosition(bar==&horizontal_?int(start):scrollX_,bar==&vertical_?int(start):scrollY_);}
void Viewport::mouseWheelMove(const MouseEvent&e,const MouseWheelDetails&w){if(e.mods.isShiftDown()||std::abs(w.deltaX)>std::abs(w.deltaY))setViewPosition(scrollX_-int((w.deltaX?w.deltaX:-w.deltaY)*120),scrollY_);else setViewPosition(scrollX_,scrollY_-int(w.deltaY*120));}
void TableHeaderComponent::addColumn(Text name,int id,int width,int minimum,int maximum,int flags){columns_.push_back({std::move(name),id,std::clamp(width,minimum,maximum),minimum,maximum,flags});repaint();}
int TableHeaderComponent::getColumnIndexFromId(int id,bool)const{for(std::size_t i=0;i<columns_.size();++i)if(columns_[i].id==id)return int(i);return -1;}
int TableHeaderComponent::getColumnWidth(int id)const{const int i=getColumnIndexFromId(id);return i>=0?columns_[std::size_t(i)].width:0;}
void TableHeaderComponent::setColumnWidth(int id,int width){const int i=getColumnIndexFromId(id);if(i>=0){auto&c=columns_[std::size_t(i)];c.width=std::clamp(width,c.minWidth,c.maxWidth);repaint();if(onGeometryChanged)onGeometryChanged();}}
int TableHeaderComponent::getTotalWidth()const{int sum=0;for(const auto&c:columns_)sum+=c.width;return sum;}
Rectangle<int>TableHeaderComponent::getColumnPosition(int index)const{int x=0;for(std::size_t i=0;i<columns_.size();++i){if(int(i)==index)return {x,0,columns_[i].width,getHeight()};x+=columns_[i].width;}return {};}
