void TableHeaderComponent::setSortColumnId(int id,bool forwards){sort_=id;forward_=forwards;if(onSort)onSort(id,forwards);repaint();}
void TableHeaderComponent::paint(Graphics&g){getLookAndFeel().drawTableHeaderBackground(g,*this);int x=0;for(const auto&column:columns_){Graphics::ScopedSaveState scope(g);g.setOrigin(x,0);g.reduceClipRegion({0,0,column.width,getHeight()});getLookAndFeel().drawTableHeaderColumn(g,*this,column.name,column.id,column.width,getHeight(),false,false,column.flags);x+=column.width;}}
